    /// <summary>
    /// had to put this here as the record returned by std code baased on personnel number is incorrect in SysDataEntityPersister\LookForUniqueKeyMatch_DSExtensions
    /// e.g. SELECT PersonnelNumber, RecId FROM HcmWorker(HcmWorker_1) WHERE ((((Person == 5637152076) || (PersonnelNumber == "000011"))))
    /// returns HcmWorker record for PersonnelNumber 0000001 with recId 5637145327
    /// instead of PersonnelNumber 000011  with recId 5637152076
    /// </summary>
    /// <param name = "_entityCtx">Data entity runtime context</param>
    /// <param name = "_dataSourceCtx">Data entity datasource runtime context</param>
    /// <returns>Common record</returns>
    public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        Common ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);        
        
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(InventBuyerGroupEntity, METHcmWorker_Orderer):
                ret = HcmWorker::findByPersonnelNumber(this.METOrdererPersonnelNumber);
                break;

            case dataEntityDataSourceStr(InventBuyerGroupEntity, METHcmWorker_Manager):
                ret = HcmWorker::findByPersonnelNumber(this.METManagerPersonnelNumber);
                break;
        }

        return ret;
    }
